function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 cars.';
  for (const car of nums) {
    if (!Array.isArray(car) || car.length !== 2) return 'Each car is a pair [start, end].';
    const [start, end] = car;
    if (!Number.isInteger(start) || !Number.isInteger(end) || start < 1 || end > 100 || start > end) return 'Each car needs 1 <= start <= end <= 100.';
  }
  return null;
}

