function numberOfPoints(nums) {
  const diff = new Array(102).fill(0);
  for (const [start, end] of nums) {
    diff[start]++;
    diff[end + 1]--;
  }

  let covering = 0;
  let points = 0;
  for (let x = 1; x <= 100; x++) {
    covering += diff[x];
    if (covering > 0) {
      points++;
    }
  }
  return points;
}

