function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const top = large || rand() < 0.3 ? 100 : 12;
  const maxLength = large ? 1 + Math.floor(rand() * 4) : 1 + Math.floor(rand() * top);
  const nums = [];
  for (let i = 0; i < n; i++) {
    const start = 1 + Math.floor(rand() * top);
    const end = Math.min(top, start + Math.floor(rand() * maxLength));
    nums.push([start, end]);
  }
  return [nums];
}
